You are working in a Blazor Web App project at `/tmp/sv-f7c0c790ce124eb08eb049b94b268d07/ShipmentTracker`. The solution has two projects:
- `ShipmentTracker` (server) — hosts the app, has EF Core with SQLite, Identity auth
- `ShipmentTracker.Client` (WASM) — client-side interactive components

The app uses Auto render mode (Server initially, then WebAssembly). Individual accounts auth is already configured.

I need you to build a shipment tracking app for a logistics company. Here's what to do:

## 1. Create Shipment model and seed data

Create `/tmp/sv-f7c0c790ce124eb08eb049b94b268d07/ShipmentTracker/ShipmentTracker/Data/Shipment.cs`:
```csharp
using System.ComponentModel.DataAnnotations;

namespace ShipmentTracker.Data;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Exception
}

public class Shipment
{
    public int Id { get; set; }

    [Required, MaxLength(20)]
    public string TrackingNumber { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    public ShipmentStatus Status { get; set; }

    public DateTime CreatedAtUtc { get; set; }
    public DateTime? EstimatedDeliveryUtc { get; set; }
    public DateTime? ActualDeliveryUtc { get; set; }

    [MaxLength(500)]
    public string? Notes { get; set; }

    // Foreign key to the customer who owns this shipment
    public string? CustomerId { get; set; }
    public ApplicationUser? Customer { get; set; }
}
```

## 2. Update ApplicationDbContext

Edit `/tmp/sv-f7c0c790ce124eb08eb049b94b268d07/ShipmentTracker/ShipmentTracker/Data/ApplicationDbContext.cs` to add a DbSet for Shipment and seed data in OnModelCreating:

```csharp
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>().HasIndex(s => s.TrackingNumber).IsUnique();

        builder.Entity<Shipment>().HasData(
            new Shipment { Id = 1, TrackingNumber = "TRK-10001", Origin = "New York, USA", Destination = "London, UK", Status = ShipmentStatus.InTransit, CreatedAtUtc = new DateTime(2026, 7, 1, 8, 0, 0, DateTimeKind.Utc), EstimatedDeliveryUtc = new DateTime(2026, 7, 10, 18, 0, 0, DateTimeKind.Utc) },
            new Shipment { Id = 2, TrackingNumber = "TRK-10002", Origin = "Tokyo, Japan", Destination = "Sydney, Australia", Status = ShipmentStatus.OutForDelivery, CreatedAtUtc = new DateTime(2026, 7, 2, 10, 0, 0, DateTimeKind.Utc), EstimatedDeliveryUtc = new DateTime(2026, 7, 8, 14, 0, 0, DateTimeKind.Utc) },
            new Shipment { Id = 3, TrackingNumber = "TRK-10003", Origin = "Berlin, Germany", Destination = "São Paulo, Brazil", Status = ShipmentStatus.Pending, CreatedAtUtc = new DateTime(2026, 7, 5, 6, 0, 0, DateTimeKind.Utc), EstimatedDeliveryUtc = new DateTime(2026, 7, 15, 20, 0, 0, DateTimeKind.Utc) },
            new Shipment { Id = 4, TrackingNumber = "TRK-10004", Origin = "Shanghai, China", Destination = "Los Angeles, USA", Status = ShipmentStatus.Delivered, CreatedAtUtc = new DateTime(2026, 6, 25, 12, 0, 0, DateTimeKind.Utc), EstimatedDeliveryUtc = new DateTime(2026, 7, 5, 16, 0, 0, DateTimeKind.Utc), ActualDeliveryUtc = new DateTime(2026, 7, 4, 14, 30, 0, DateTimeKind.Utc) },
            new Shipment { Id = 5, TrackingNumber = "TRK-10005", Origin = "Mumbai, India", Destination = "Dubai, UAE", Status = ShipmentStatus.PickedUp, CreatedAtUtc = new DateTime(2026, 7, 7, 9, 0, 0, DateTimeKind.Utc), EstimatedDeliveryUtc = new DateTime(2026, 7, 12, 10, 0, 0, DateTimeKind.Utc) }
        );
    }
}
```

## 3. Create a shared DTO in the Client project

Create `/tmp/sv-f7c0c790ce124eb08eb049b94b268d07/ShipmentTracker/ShipmentTracker.Client/ShipmentDto.cs`:
```csharp
namespace ShipmentTracker.Client;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Exception
}

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedAtUtc { get; set; }
    public DateTime? EstimatedDeliveryUtc { get; set; }
    public DateTime? ActualDeliveryUtc { get; set; }
    public string? Notes { get; set; }
}
```

## 4. Create an API controller on the server for shipments

Create `/tmp/sv-f7c0c790ce124eb08eb049b94b268d07/ShipmentTracker/ShipmentTracker/ShipmentEndpoints.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;

namespace ShipmentTracker;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        group.MapGet("/", async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.CreatedAtUtc)
                .Select(s => new Client.ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = (Client.ShipmentStatus)(int)s.Status,
                    CreatedAtUtc = s.CreatedAtUtc,
                    EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
                    ActualDeliveryUtc = s.ActualDeliveryUtc,
                    Notes = s.Notes
                })
                .ToListAsync();
            return Results.Ok(shipments);
        });

        group.MapGet("/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .Where(s => s.TrackingNumber == trackingNumber)
                .Select(s => new Client.ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = (Client.ShipmentStatus)(int)s.Status,
                    CreatedAtUtc = s.CreatedAtUtc,
                    EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
                    ActualDeliveryUtc = s.ActualDeliveryUtc,
                    Notes = s.Notes
                })
                .FirstOrDefaultAsync();

            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });

        group.MapPut("/{id:int}/status", async (int id, UpdateStatusRequest request, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = (Data.ShipmentStatus)(int)request.Status;
            if (request.Status == Client.ShipmentStatus.Delivered)
                shipment.ActualDeliveryUtc = DateTime.UtcNow;

            await db.SaveChangesAsync();
            return Results.Ok();
        });
    }

    public record UpdateStatusRequest(Client.ShipmentStatus Status);
}
```

## 5. Register endpoints in Program.cs

Edit `/tmp/sv-f7c0c790ce124eb08eb049b94b268d07/ShipmentTracker/ShipmentTracker/Program.cs`. Add `using ShipmentTracker;` at the top and before `app.Run();` add:
```csharp
app.MapShipmentEndpoints();
```

Also add HttpClient registration for the WASM client. After the `builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();` line add:
```csharp
builder.Services.AddHttpClient();
```

## 6. Register HttpClient in the Client project

Edit `/tmp/sv-f7c0c790ce124eb08eb049b94b268d07/ShipmentTracker/ShipmentTracker.Client/Program.cs` to register HttpClient. The file should be:
```csharp
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();
builder.Services.AddScoped(sp => new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });

await builder.Build().RunAsync();
```

## 7. Create the Dispatcher Dashboard page (Client project)

Create `/tmp/sv-f7c0c790ce124eb08eb049b94b268d07/ShipmentTracker/ShipmentTracker.Client/Pages/Shipments.razor`:
```razor
@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject HttpClient Http

<PageTitle>Shipments Dashboard</PageTitle>

<h2>Shipments Dashboard</h2>

<div class="mb-3 row">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Filter by tracking # or destination..."
               @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-primary" @onclick="LoadShipments">
            <span class="bi bi-arrow-clockwise"></span> Refresh
        </button>
    </div>
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments match your filter.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><strong>@shipment.TrackingNumber</strong></td>
                        <td>@shipment.Origin</td>
