OK so we DO need HttpClient on the server. Let me just use the `IHttpContextAccessor` approach and also forward the auth cookie:

```csharp
builder.Services.AddHttpContextAccessor();
builder.Services.AddScoped(sp =>
{
    var factory = sp.GetRequiredService<IHttpClientFactory>();
    var client = factory.CreateClient();
    var httpContextAccessor = sp.GetService<IHttpContextAccessor>();
    var request = httpContextAccessor?.HttpContext?.Request;
    if (request is not null)
    {
        client.BaseAddress = new Uri($"{request.Scheme}://{request.Host}");
        // Forward auth cookies for prerendering
        if (request.Headers.TryGetValue("Cookie", out var cookies))
        {
            client.DefaultRequestHeaders.Add("Cookie", cookies.ToString());
        }
    }
    return client;
