using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;

namespace ShipmentTracker;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        group.MapGet("/", async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.CreatedAtUtc)
                .Select(s => new Client.ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = (Client.ShipmentStatus)(int)s.Status,
                    CreatedAtUtc = s.CreatedAtUtc,
                    EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
                    ActualDeliveryUtc = s.ActualDeliveryUtc,
                    Notes = s.Notes
                })
                .ToListAsync();
            return Results.Ok(shipments);
        });

        group.MapGet("/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .Where(s => s.TrackingNumber == trackingNumber)
                .Select(s => new Client.ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = (Client.ShipmentStatus)(int)s.Status,
                    CreatedAtUtc = s.CreatedAtUtc,
                    EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
                    ActualDeliveryUtc = s.ActualDeliveryUtc,
                    Notes = s.Notes
                })
                .FirstOrDefaultAsync();

            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });

        group.MapPut("/{id:int}/status", async (int id, UpdateStatusRequest request, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = (Data.ShipmentStatus)(int)request.Status;
            if (request.Status == Client.ShipmentStatus.Delivered)
                shipment.ActualDeliveryUtc = DateTime.UtcNow;

            await db.SaveChangesAsync();
            return Results.Ok();
        });
    }

    public record UpdateStatusRequest(Client.ShipmentStatus Status);
}
```

