    <div class="alert alert-warning">@errorMessage</div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <h4 class="mb-0">Shipment @shipment.TrackingNumber</h4>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                        <dt>Shipped On</dt>
                        <dd>@shipment.CreatedAtUtc.ToString("MMMM dd, yyyy")</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span></dd>
                        <dt>Estimated Delivery</dt>
                        <dd>
                            @if (shipment.EstimatedDeliveryUtc.HasValue)
                            {
                                <strong>@shipment.EstimatedDeliveryUtc.Value.ToString("MMMM dd, yyyy 'at' HH:mm 'UTC'")</strong>
                            }
                            else
                            {
                                <span>Not yet available</span>
                            }
                        </dd>
                        @if (shipment.ActualDeliveryUtc.HasValue)
                        {
                            <dt>Delivered On</dt>
                            <dd class="text-success">@shipment.ActualDeliveryUtc.Value.ToString("MMMM dd, yyyy 'at' HH:mm 'UTC'")</dd>
